/// A simple random‐bit generator struct.
/// 
/// - `initialized` is always true for a generator returned by `default_rng`.
/// - `seed` holds exactly the `Option<u64>` that was given.
/// - `state` is derived from `seed` by `compute_state`: non‐zero if `seed.is_some()`.
#[derive(Debug, Clone)]
pub struct Generator {
    pub initialized: bool,
    pub seed: Option<u64>,
    pub state: u64,
}

/// Compute an internal state from an optional 64‐bit seed.
///
/// - If `seed` is `None`, returns 0.
/// - If `seed` is `Some(s)` and `s != 0`, returns `s`.
/// - If `seed` is `Some(0)`, returns 1 to ensure non‐zero.
pub fn compute_state(seed: Option<u64>) -> u64 {
    match seed {
        None => 0,
        Some(0) => 1,
        Some(s) => s,
    }
}

/// Construct a new generator from an optional seed.
///
/// - The returned generator is marked initialized (`initialized: true`).
/// - It stores exactly the given `seed`.
/// - Its `state` is computed via `compute_state`, so it is non‐zero if `seed.is_some()`.
pub fn default_rng(seed: Option<u64>) -> Generator {
    let state = compute_state(seed);
    Generator {
        initialized: true,
        seed,
        state,
    }
}

